    initial_bounds = {}
    for name, interval in roots.items():
        initial_bounds.setdefault(name, []).append((interval[0], interval[1]))

    best_key = None
    best_versions = None

    def search(required, chosen, bounds):
        nonlocal best_key, best_versions

        pending = sorted(required - chosen.keys())
        if not pending:
            key = tuple(chosen.get(name, {}).get("version", -1) for name in names)
            if best_key is None or key > best_key:
                best_key = key
                best_versions = {
                    name: row["version"] for name, row in chosen.items()
                }
            return

        name = pending[0]
        for row in packages.get(name, []):
            version = row["version"]
            if any(version < low or version > high
                   for low, high in bounds.get(name, [])):
                continue
            if version in blocked.get(name, []):
                continue
            if name in pins and version != pins[name]:
                continue

            next_chosen = dict(chosen)
            next_chosen[name] = row
            next_required = set(required)
            next_bounds = {pkg: list(ranges) for pkg, ranges in bounds.items()}
            valid = True

            for dep in active_dependencies(row, features):
                dep_name = dep["name"]
                low, high = dep["min"], dep["max"]
                next_required.add(dep_name)
                next_bounds.setdefault(dep_name, []).append((low, high))
