                    dep_version = next_chosen[dep_name]["version"]
                    if dep_version < low or dep_version > high:
                        valid = False
                        break

            if valid:
                search(next_required, next_chosen, next_bounds)

    search(set(roots), {}, initial_bounds)
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}
